mapper.select:
select t.job_ins_id, t.job_id, t.task_ins_id, t.task_id, t.task_state, t.batch, t.task_name, t.use_job_dimension, t.task_plugin, t.program_name, t.error_delay, t.error_ignore, t.error_max_num, t.error_current_num, t.period, t.working_day, t.task_result, t.information, t.next_execute_time, t.agent_scope, t.agent, t.task_parameter, t.begin_time, t.end_time, t.create_time, t.creator, t.allowed_rerun from ww_task_instance t where 1=1
and t.job_ins_id = #{jobInsId}
and t.task_state = #{state}
and t.task_ins_id = #{taskInsId}
and instr(t.task_ins_id, #{lTaskInsId}) > 0
and t.task_id = #{taskId}
and instr(t.task_id, #{lTaskId}) > 0
order by t.begin_time desc

mapper.update:
update ww_task_instance t
t.error_delay = #{errorDelay},
t.error_max_num = #{maxNumOfExeErrors},
t.error_current_num = #{currentErrorExeCount},
t.agent_scope = #{agentScope}, t.period = #{period}, t.working_day = #{workingDay}, t.next_execute_time = #{nextExecuteTime}, t.task_parameter = #{parameters}
where t.job_ins_id = #{jobInsId} and t.task_ins_id = #{taskInsId}

mapper.select:
select j.product,j.batch, MIN(t.begin_time) begin_time, MAX(t.end_time) end_time, COUNT(1) AS total_count, COUNT(IF(t.task_state = 11, TRUE, NULL)) init_count, COUNT(IF(t.task_state = 12, TRUE, NULL)) ready_count, COUNT(IF(t.task_state = 13, TRUE, NULL)) running_count, COUNT(IF(t.task_state = 14, TRUE, NULL)) error_delay_count, COUNT(IF(t.task_state = 15, TRUE, NULL)) feedback_count, COUNT(IF(t.task_state = 16, TRUE, NULL)) failed_count, COUNT(IF(t.task_state = 17, TRUE, NULL)) manual_count, COUNT(IF(t.task_state = 18, TRUE, NULL)) period_delay_count, COUNT(IF(t.task_state > 19, TRUE, NULL)) passed_count from ww_job_instance j left join ww_task_instance t on j.job_ins_id = t.job_ins_id where 1=1
and j.product = #{product}
and j.batch = #{batch}
group by j.product,j.batch

select j.product,j.batch, MIN(t.begin_time) "begin_time", MAX(t.end_time) "end_time", COUNT(1) AS "total_count", COUNT(DECODE(t.task_state,11,1,NULL)) AS "init_count", COUNT(DECODE(t.task_state,12,1,NULL)) AS "ready_count", COUNT(DECODE(t.task_state,13,1,NULL)) AS "running_count", COUNT(DECODE(t.task_state,14,1,NULL)) AS "error_delay_count", COUNT(DECODE(t.task_state,15,1,NULL)) AS "feedback_count", COUNT(DECODE(t.task_state,16,1,NULL)) AS "failed_count", COUNT(DECODE(t.task_state,17,1,NULL)) AS "manual_count", COUNT(DECODE(t.task_state,18,1,NULL)) AS "period_delay_count", COUNT(DECODE(SIGN(t.task_state-19),1,1,NULL)) AS "passed_count" from ww_job_instance j left join ww_task_instance t on j.job_ins_id = t.job_ins_id where 1=1
and j.product = #{product}
and j.batch = #{batch}
group by j.product,j.batch

select information from ww_task_instance 
where 1=1


and job_ins_id=#{jobInsId}

and task_ins_id=#{taskInsId}
